-- The deterministic setup worker really settles its own job.
select public.worker_record_agent_response_and_activate_v7(p_job_id=>current_setting('test.setup_job')::uuid,p_capability_token=>current_setting('test.setup_cap'),p_capture_id=>null,p_assistant_message_id=>gen_random_uuid(),p_response=>jsonb_build_object('state','idle','reply','Configuração preparada para revisão humana.'));
select public.worker_complete_job(current_setting('test.setup_job')::uuid,current_setting('test.setup_cap'),'{}'::jsonb);
select pg_temp.as_owner();
select public.set_capital_project_review_policy_v1((select capital_project_id from public.document_intake_sessions where id='d5300000-0000-4000-8000-000000000001'),'allowed');
select set_config('test.setup_review_basis',public.read_institutional_configuration_review_basis_v2((select capital_project_id from public.document_intake_sessions where id='d5300000-0000-4000-8000-000000000001'),current_setting('test.setup_candidate_id')::uuid)::text,true);
select public.review_institutional_configuration_and_calculate_v2((select capital_project_id from public.document_intake_sessions where id='d5300000-0000-4000-8000-000000000001'),current_setting('test.setup_candidate_id')::uuid,
 current_setting('test.setup_review_basis')::jsonb->>'parentFingerprint','approved',current_setting('test.setup_review_basis')::jsonb->>'configurationFingerprint',current_setting('test.setup_review_basis')::jsonb->>'lineageFingerprint',gen_random_uuid(),'en-US',true);
reset role;
